/**
 * kernel_config.js — source-of-truth for kernel runtime loading.
 *
 * Hand-written for now; will eventually be generated by the build from a
 * profile (see docs/proposal-configurable-build-and-kernel-sources.md).
 *
 * The runtime (KernelManager.loadKernelSource) tries the kernel's primary URL
 * (which still honors any version override), then the `sources` listed here, in
 * order, each with a per-attempt timeout (timeoutMs). A slow/dead source fails
 * fast and falls through instead of hanging the WASM thread (which otherwise
 * gets the WebView renderer killed).
 *
 * Per-kernel override: localStorage['scirepl_<lang>_source'] = a URL (tried
 * first) or 'local' (prefer a bundled source, when one exists).
 *
 * `sources` entries: { type: 'cdn' | 'local', url }. Empty `sources` means
 * "primary only" — the timeout still applies. Mirror URLs are added here as
 * they're verified; bundled `local` entries are added by the build profile.
 */
window.KERNEL_CONFIG = {
  profile: 'light',
  languages: {
    // swipl-wasm: official browser build is github.io-hosted with a custom
    // layout that doesn't map cleanly to jsdelivr/unpkg, so no verified mirror
    // yet. The timeout still converts a stall into a recoverable error.
    prolog: { enabled: true, timeoutMs: 60000, sources: [] },
    // Pyodide primary is pyodide/v0.27.4/full/pyodide.js (kernel default).
    // Mirrors below are the npm-packaged 0.27.4 build (verified 200); keep the
    // version in sync with kernels/python.js when bumping.
    python: { enabled: true, timeoutMs: 120000, sources: [
      { type: 'cdn', url: 'https://cdn.jsdelivr.net/npm/pyodide@0.27.4/pyodide.js' },
      { type: 'cdn', url: 'https://unpkg.com/pyodide@0.27.4/pyodide.js' },
    ] },
    r:      { enabled: true, timeoutMs: 180000, sources: [] },
    // Fengari primary is the jsdelivr 0.1.4 build (kernel default); unpkg mirror
    // verified 200. Keep the version in sync with kernels/lua.js when bumping.
    lua:    { enabled: true, timeoutMs: 30000, sources: [
      { type: 'cdn', url: 'https://unpkg.com/fengari-web@0.1.4/dist/fengari-web.js' },
    ] },
  },
};
